    // |u| clamped to 1.0
    wire        neg   = u_q30[31];
    wire [31:0] u_abs = neg ? (~u_q30 + 32'd1) : u_q30;
    wire [30:0] ua    = (u_abs >= {1'b0, ONE}) ? ONE : u_abs[30:0];
    wire        fine  = (ua >= FINE_BASE);
    wire        one   = (ua == ONE);

    // coarse: segment = ua[30:20], fraction = ua[19:0]
    // fine  : (ua - FINE_BASE) spans 2^25 -> segment = [24:15], fraction = [14:0]
    wire [30:0] uf    = ua - FINE_BASE;
    wire [10:0] addr0 = fine ? (11'd1023 + {1'b0, uf[24:15]}) : ua[30:20];
    wire [10:0] addr1 = addr0 + 11'd1;
    wire [19:0] frac  = fine ? {uf[14:0], 5'd0} : ua[19:0];

    reg  [29:0] t0, t1;
    reg  [19:0] frac_r;
    reg         neg_r, one_r, v1;

    // stage 1: dual-port synchronous ROM read (no reset -> block RAM)
    always @(posedge clk) begin
        t0 <= rom[addr0];
        t1 <= rom[addr1];
    end

    always @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            valid_out <= 1'b0;
            theta_q28 <= 32'sd0;
            frac_r <= 20'd0; neg_r <= 1'b0; one_r <= 1'b0;
        end else begin
            v1     <= valid_in;
            frac_r <= frac;
            neg_r  <= neg;
            one_r  <= one;
            // stage 2: linear interpolation
            valid_out <= v1;
            if (v1)
                theta_q28 <= neg_r ? -interp(t0, t1, frac_r, one_r) : interp(t0, t1, frac_r, one_r);
        end
    end

    function signed [31:0] interp;
        input [29:0] a;
        input [29:0] b;
        input [19:0] f;
        input        is_one;
        reg   [49:0] dlt;
        begin
            dlt    = {20'd0, b - a} * f;     // b >= a (asin is monotonic)
            interp = is_one ? $signed({2'b00, HALF_PI})
                            : $signed({2'b00, a}) + $signed({2'b00, dlt[49:20]});
        end
    endfunction

endmodule
